<?= $this->extend('resources/layout') ?><?= $this->section('content') ?>
<?php if ($admin): ?><form method="get" class="filters"><label>Student<input name="student" value="<?= esc($filters['student'],'attr') ?>"></label><label>Reservation #<input name="reservation" inputmode="numeric" value="<?= esc($filters['reservation'],'attr') ?>"></label><label>Method<select name="method"><option value="">All</option><?php foreach(['card'=>'Card','gcash'=>'GCash','bank_transfer'=>'Bank Transfer'] as $v=>$l): ?><option value="<?= $v ?>" <?= $filters['method']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach ?></select></label><label>Status<select name="status"><option value="">All</option><?php foreach(['pending','paid','failed','cancelled','expired','refunded'] as $v): ?><option <?= $filters['status']===$v?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></label><label>Date<input type="date" name="date" value="<?= esc($filters['date'],'attr') ?>"></label><button>Filter</button><?php if(array_filter($filters)): ?><a class="button" href="<?= site_url('admin/payments') ?>">Clear filters</a><?php endif ?></form><?php endif ?>
<div class="table-wrap"><table><thead><tr><?php if($admin): ?><th>Student</th><?php endif ?><th>Reservation</th><th>Transaction</th><th>Method</th><th>Amount</th><th>Date</th><th>Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><?php if($admin): ?><td><?= esc($payment['full_name']) ?><br><small><?= esc($payment['student_id']) ?></small></td><?php endif ?><td>#<?= (int)$payment['reservation_id'] ?></td><td><?= esc($payment['transaction_reference']) ?></td><td><?= esc(ucwords(str_replace('_',' ',$payment['payment_method']))) ?></td><td><?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></td><td><?= esc($payment['paid_at'] ?? $payment['created_at']) ?></td><td><?= esc(ucfirst($payment['payment_status'])) ?></td><td><?php if($payment['payment_status'] !== 'pending'): ?><a href="<?= site_url(($admin?'admin':'borrower').'/payments/'.$payment['id'].'/receipt') ?>">Receipt</a><?php endif ?></td></tr><?php endforeach ?><?php if(!$payments): ?><tr><td colspan="<?= $admin?8:7 ?>">No payment transactions match.</td></tr><?php endif ?></tbody></table></div>
<?= $this->endSection() ?>
